import{_ as t,b as a,e as r,a8 as o}from"./chunks/framework.C-MVLAPI.js";const i="/assets/GR32_R-compile.DE_6lC92.png",s="/assets/GR32_D-install.Cs8fzNLD.png",l="/assets/GR32_D-after-install.C_sAZatR.png",n="/assets/LazarusRecompileClean.D4Cdt8OB.png",c="/assets/LazarusCompileResult.DIMqDFqn.png",p="/assets/LazarusUseInstall.D1ZbMoCj.png",k=JSON.parse('{"title":"Installation","description":"","frontmatter":{"date":1788304505000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1788304505000,"timestamp":1788304505000,"datetime":"2026-09-01T23:15:05.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),h={name:"guide/installation.md"};function u(d,e,g,m,f,_){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><h2 id="get-the-source-code" tabindex="-1">Get the source code <a class="header-anchor" href="#get-the-source-code" aria-label="Permalink to &quot;Get the source code&quot;">​</a></h2><p>You can get the latest source code from the Graphics32 Git repository. Either using a Git client to clone the repository or by simply downloading a zip file with the latest snapshot.</p><ul><li>Git: <a href="https://github.com/graphics32/graphics32.git" target="_blank" rel="noreferrer">https://github.com/graphics32/graphics32.git</a></li><li>Zip file: <a href="https://github.com/graphics32/graphics32/archive/refs/heads/master.zip" target="_blank" rel="noreferrer">https://github.com/graphics32/graphics32/archive/refs/heads/master.zip</a></li></ul><p>Copy the source code to a location of your choice. In the installation procedures below we use the location <code>C:\\Projects\\Graphics32</code> as an example.</p><h2 id="installation-procedure-for-delphi-c-builder-rad-studio" tabindex="-1">Installation procedure for Delphi / C++ Builder / RAD Studio <a class="header-anchor" href="#installation-procedure-for-delphi-c-builder-rad-studio" aria-label="Permalink to &quot;Installation procedure for Delphi / C++ Builder / RAD Studio&quot;">​</a></h2><p>Note: While the following procedure only mentions Delphi it applies to both Delphi and C++ Builder.</p><ol><li>Start Delphi.</li><li>Add the location of the Graphics32 source to the global library search path. You can skip this step if you prefer to use per-project library search paths for your own projects. All of Graphics32’s own packages and examples use per-project search paths so they don’t require the source to be in the global search path. <ol><li>From the menu select <strong>Tools</strong> →<strong>Options…</strong></li><li>Select <strong>Language</strong> →<strong>Delphi</strong> →<strong>Library</strong>.</li><li>Select the <strong>Library path</strong> field and add the source folder location: <code>C:\\Projects\\Graphics32\\Source</code>.</li><li>Do the above for all the required platforms; Windows 32-bit, Windows 64-bit, etc.</li></ol></li><li>From the menu, select <strong>File</strong> →<strong>Open project…</strong></li><li>Navigate to the <code>Grapics32\\Source\\Packages</code> folder and from there open the package folder that corresponds to your version of Delphi. Note that Delphi 11 and later versions all use the same package files.</li><li>Open the <code>Graphics32_packages.groupproj</code> project group file. The project group contains two projects: <ul><li>The Graphics32 run-time package: <code>GR32_R</code></li><li>The Graphics32 design-time package: <code>GR32_D</code></li></ul></li><li>From the Delphi project manager, activate the Graphics32 run-time package and compile it. <img src="'+i+'" alt=""></li><li>From the Delphi project manager, activate the Graphics32 design-time package and install it. <img src="'+s+'" alt=""></li><li>You should now get a message box notifying you of the package installation and the components it contains: <img src="'+l+'" alt=""></li></ol><h2 id="installation-procedure-for-lazarus" tabindex="-1">Installation procedure for Lazarus <a class="header-anchor" href="#installation-procedure-for-lazarus" aria-label="Permalink to &quot;Installation procedure for Lazarus&quot;">​</a></h2><p>The installation procedure for Lazarus is pretty horrible due to deficiencies in the FreePascal compiler or the Lazarus build system.</p><ol><li>Open the <code>GR32_Lazarus</code> run-time package. . Select <strong>Recompile clean</strong> from the <strong>More</strong> package toolbar menu. <img src="'+n+'" alt=""></li><li>Compile <code>GR32_Lazarus</code> again. Repeat this 3-4 times until the compile completes without any messages. <img src="'+c+'" alt=""></li><li>Open the <code>GR32_DSGN_Lazarus</code> design-time package. Select <strong>Use</strong> →<strong>Install</strong> from the package toolbar. <img src="'+p+'" alt=""></li></ol><p>See also:</p><ul><li><a href="https://github.com/graphics32/graphics32/issues/297#issuecomment-2050525983" target="_blank" rel="noreferrer">Graphics32, issue 297: Lazarus design time support broken</a></li><li><a href="https://gitlab.com/freepascal.org/fpc/source/-/issues/12223" target="_blank" rel="noreferrer">FreePascal, issue 12223: Unit with inline, and recursive uses, needs recompilation right after compilation</a></li><li><a href="https://gitlab.com/freepascal.org/fpc/source/-/issues/15221" target="_blank" rel="noreferrer">FreePascal, issue 15221: Checksum issue</a></li><li><a href="https://gitlab.com/freepascal.org/fpc/source/-/issues/19673" target="_blank" rel="noreferrer">FreePascal, issue 19673: Problems with circular references and inline procedures.</a></li></ul>',13)])])}const G=t(h,[["render",u]]);export{k as __pageData,G as default};
